# area: gradual_any
# hypothesis: A method of class C, defined before class B whose __init__ declares the Optional[int] attribute _foo, assigns a value from a function decorated with a generic deco that is defined later, so checkers may disagree on the type revealed for b._foo before and after the assignment.
from typing import Callable, Optional, TypeVar, reveal_type

T = TypeVar('T')


def deco(fn: Callable[[], T]) -> Callable[[], T]:
    def inner() -> T:
        return fn()
    return inner


class C:
    def a(self) -> Optional[int]:
        b = B()
        reveal_type(b._foo)
        b._foo = defer()
        return b._foo


class B:
    def __init__(self) -> None:
        self._foo: Optional[int] = None


@deco
def defer() -> int:
    return 5


c = C()
reveal_type(c.a())
print(c.a())
